{
  "checks": [
    {
      "candidate_id": "pm",
      "verdict": "SUPPORT",
      "reason": "PM is the explicitly named participant in the organization obligation.",
      "sources": [{"quote": "PM must organize", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "organize",
      "verdict": "SUPPORT",
      "reason": "The main organization event is explicitly required by must.",
      "sources": [{"quote": "PM must organize a review", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "review",
      "verdict": "SUPPORT",
      "reason": "Review is the complement of organize. The source does not separately require PM to perform the review.",
      "sources": [{"quote": "organize a review", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "staging",
      "verdict": "SUPPORT",
      "reason": "Staging resources identify the review's permitted scope; no modification of those resources is asserted.",
      "sources": [{"quote": "a review limited to staging resources", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "production",
      "verdict": "SUPPORT",
      "reason": "Production resources are explicitly the material excluded from the review scope.",
      "sources": [{"quote": "exclude production resources", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "exclude",
      "verdict": "SUPPORT",
      "reason": "Exclude is coordinated with organize under PM must. Its interpretation as review-scope exclusion is supported by the surrounding review restriction.",
      "sources": [{"quote": "PM must organize a review limited to staging resources and exclude production resources", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "deliverable_declaration",
      "verdict": "SUPPORT",
      "reason": "The sentence declares a deliverable identity. Its declaration layer and unstated action modality avoid inventing a separate production event.",
      "sources": [{"quote": "The deliverable is staging-scope.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "deliverable",
      "verdict": "SUPPORT",
      "reason": "The named file is explicitly designated as the deliverable, supporting its output classification without identifying a producer or production method.",
      "sources": [{"quote": "The deliverable is staging-scope.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "configuration",
      "verdict": "SUPPORT",
      "reason": "Configuration is the affected material of the prohibited changes. MODIFICATION_TARGET does not itself authorize modification.",
      "sources": [{"quote": "no configuration changes are allowed", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "modify_configuration",
      "verdict": "SUPPORT",
      "reason": "The affirmative change operation is explicitly forbidden; it is not a required or permitted action.",
      "sources": [{"quote": "no configuration changes are allowed", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r1",
      "verdict": "SUPPORT",
      "reason": "PM is the grammatical actor of organize, providing participation evidence beyond the role name.",
      "sources": [{"quote": "PM must organize", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r2",
      "verdict": "NO_EVIDENCE",
      "reason": "The source establishes review as the complement of organize, but does not establish the review event as a constituent event of organizing it.",
      "sources": [{"quote": "organize a review", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r3",
      "verdict": "SUPPORT",
      "reason": "The coordinated verb exclude shares the explicit subject PM.",
      "sources": [{"quote": "PM must organize a review limited to staging resources and exclude production resources", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r4",
      "verdict": "SUPPORT",
      "reason": "Production resources are the direct object of exclude.",
      "sources": [{"quote": "exclude production resources", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r5",
      "verdict": "SUPPORT",
      "reason": "And coordinates organize and exclude under the shared subject and modal.",
      "sources": [{"quote": "PM must organize a review limited to staging resources and exclude production resources", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r6",
      "verdict": "SUPPORT",
      "reason": "The review is explicitly associated with a staging scope that excludes production. This relation supports scope association when read together with r7.",
      "sources": [{"quote": "a review limited to staging resources and exclude production resources", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r7",
      "verdict": "SUPPORT",
      "reason": "Limited to explicitly restricts the review scope.",
      "sources": [{"quote": "a review limited to staging resources", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r8",
      "verdict": "NO_EVIDENCE",
      "reason": "The source identifies the deliverable; it does not establish that the declaration event produces the file as its result.",
      "sources": [{"quote": "The deliverable is staging-scope.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r9",
      "verdict": "SUPPORT",
      "reason": "Configuration is the patient of the prohibited change operation.",
      "sources": [{"quote": "configuration changes", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "r10",
      "verdict": "SUPPORT",
      "reason": "The task text explicitly forbids configuration changes without limiting the prohibition to a particular environment.",
      "sources": [{"quote": "no configuration changes are allowed", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "staging_scope",
      "verdict": "SUPPORT",
      "reason": "Staging resources explicitly identify the included review scope.",
      "sources": [{"quote": "a review limited to staging resources", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "production_scope",
      "verdict": "SUPPORT",
      "reason": "Production resources identify the exclusion operand. The ITEM expression does not independently assert their inclusion.",
      "sources": [{"quote": "exclude production resources", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    },
    {
      "candidate_id": "review_scope",
      "verdict": "SUPPORT",
      "reason": "The combined restriction supports staging resources with production resources excluded; no overlap between those resource sets needs to be assumed.",
      "sources": [{"quote": "limited to staging resources and exclude production resources", "clause_id": "c1", "occurrence": 0, "context_anchor": null}]
    }
  ],
  "findings": [
    {
      "id": "f1",
      "kind": "WRONG_BINDING",
      "candidate_ids": ["r2"],
      "sources": [{"quote": "organize a review", "clause_id": "c1", "occurrence": 0, "context_anchor": null}],
      "reason": "PART_OF substitutes event composition for a complement relationship. Organizing a review does not establish that conducting the review is part of the organization event. The review node already preserves the complement ownership."
    },
    {
      "id": "f2",
      "kind": "WRONG_BINDING",
      "candidate_ids": ["r8"],
      "sources": [{"quote": "The deliverable is staging-scope.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}],
      "reason": "RESULT binds the file to the declaration event as a produced result. The explicit meaning is deliverable designation; neither a file-producing event nor its actor is supplied."
    }
  ],
  "coverage": [
    {
      "region_id": "c1",
      "disposition": "UNPARSED",
      "candidate_ids": ["pm", "organize", "review", "staging", "production", "exclude", "deliverable_declaration", "deliverable", "configuration", "modify_configuration", "r1", "r2", "r3", "r4", "r5", "r6", "r7", "r8", "r9", "r10", "staging_scope", "production_scope", "review_scope"],
      "reason": "The obligations, scope restriction, deliverable identity, and prohibition have supporting representations, but the review complement and deliverable designation have unreliable relation bindings in r2 and r8. The region therefore does not qualify as a fully reliable boundary parse."
    }
  ],
